package com.compcorp.commerce.batch;
import com.fasterxml.jackson.databind.ObjectMapper;import java.io.*;import java.nio.file.*;import java.time.Instant;import java.util.*;
public final class BatchReportExporter {private BatchReportExporter(){} public static void write(OrderCsvImporter.Result result,Path output)throws IOException{Map<String,Object> report=new LinkedHashMap<>();report.put("processedAt",Instant.now().toString());report.put("acceptedCount",result.accepted().size());report.put("rejectedCount",result.rejected().size());report.put("acceptedTotal",result.total());report.put("accepted",result.accepted());report.put("rejected",result.rejected());Path parent=output.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();try(OutputStream stream=Files.newOutputStream(output)){mapper.writerWithDefaultPrettyPrinter().writeValue(stream,report);}}}
